import{_ as s,l as i,o as e,c as l,v as t,p,x as r,d,i as n,S as c}from"./chunks/framework.InCnrqk-.js";const g=JSON.parse('{"title":"透明大页 THP","description":"","frontmatter":{"title":"透明大页 THP","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/thp.md","filePath":"cs/thp.md","lastUpdated":1789023840000}'),h={name:"cs/thp.md"};function m(u,a,T,_,B,P){const o=i("Mermaid");return e(),l("div",null,[a[1]||(a[1]=t('<h1 id="透明大页-thp" tabindex="-1">透明大页 THP <a class="header-anchor" href="#透明大页-thp" aria-label="Permalink to &quot;透明大页 THP&quot;">​</a></h1><div class="epigraph"><p>THP 在匿名（及部分文件）映射上自动用 2MB 页：少页表、少 TLB 失配，失败则拆回 4KB。</p><footer>—— 据 Linux transhuge 文档；Navarro 等对超级页的背景；Gorman 对 THP 的整理</footer></div><p><a href="/cs/page-migration-compaction">compaction</a> 为的是交出连续 512 个 4K 框。<a href="/cs/tlb-translate">TLB</a> 主干已说明大页的好处。缺口是 <strong>透明</strong>：应用不 <code>hugetlbfs</code> 也能用，以及拆页与延迟。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p><code>mmap</code> 匿名区默认可被 khugepaged 扫描折叠，或缺页时直接分配大页（always/madvise）。缺口：内部碎片（只用 1 字节也占 2MB）；NUMA 跨节点大页更痛；fork COW 要拆或整页拷；与 <a href="/cs/rmap">rmap</a> ——一条 pmd 映射，反查粒度变粗。本课不把 hugetlb 预留池写成运维手册。</p><p><span class="marginnote"><code>madvise(MADV_HUGEPAGE)</code> 是 always 之外的选择。禁用 THP 是数据库常见旋钮，因为延迟尾部。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>缺页：尝试 <code>alloc_hugepage</code>，失败则 4K。khugepaged：找对齐的 4K 序列，compact，安装 pmd。拆：写保护 COW、部分 madvise 或内存紧张。对照 <a href="/cs/ext4-extents">extent</a>：连续虚存 ↔ 连续物理。对照 DAX：大页映射 PMEM 是另一配置。</p>',8)),(e(),p(c,null,{default:r(()=>[n(o,{id:"mermaid-22",class:"mermaid",graph:"flowchart%20TD%0A%20%20FAULT%5B%22%E5%8C%BF%E5%90%8D%E7%BC%BA%E9%A1%B5%22%5D%20--%3E%20TRY%5B%22%E8%AF%95%202MB%22%5D%0A%20%20TRY%20--%3E%7C%22%E5%A4%B1%E8%B4%A5%22%7C%204K%5B%224KB%20%E9%A1%B5%22%5D%0A%20%20SCAN%5B%22khugepaged%22%5D%20--%3E%20COL%5B%22%E6%8A%98%E5%8F%A0%E5%B7%B2%E6%9C%89%204K%22%5D%0A%20%20COW%5B%22COW%20%E5%86%99%22%5D%20--%3E%20SPLIT%5B%22%E6%8B%86%20pmd%22%5D%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[d(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>THP 把 TLB 覆盖范围加大，用碎片与延迟换吞吐。它是透明的，因而错误默认会伤害延迟敏感负载。不要写成 CPU 硬件预取。与 <a href="/cs/memcg">cgroup</a>：大页占用按 2MB 记账，限制更易触顶。</p><p>调试：<code>/proc/vmstat</code> 的 thp 计数；拆页失败会泄漏或回退。</p><p>实现上：khugepaged 扫描会占用 CPU，桌面发行版常把 defrag 设成 madvise。拆页失败可能留下分裂中的 pmd，要重试。文件 THP 对 tmpfs 有意义，对磁盘 FS 仍受限。 读法上只引用<a href="/cs/page-migration-compaction">上一课</a>的结论，不把对象换成训练推理或限价簿。</p><p>本课在操作系统进阶的「内存进阶 / 回收、迁移与加固」课序里，对象是 <strong>透明大页 THP</strong>。</p><ul><li>先修只引用，不重导：上一课的结论当公理，本课只补差。</li><li>五栏不吞并：不把本课写成大模型训练/推理，也不写成限价簿或权重量化。</li><li>文献用 OSTEP、McKusick、内核文档与具名会议论文；不发明 arXiv 编号。</li></ul><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不引入 1GB 页的全部引导参数。不保证文件 THP（shmem/tmpfs）在所有版本默认开。下一课另一条「合并物理页」：KSM 按内容。</p><p>版本字段会变，课序钉的是机制对象「透明大页 THP」，不是某一主线内核的结构体名。 后课默认：内核可透明使用匿名大页。按内容合并相同页，下一课 KSM。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>THP 自动用 2MB，失败或 COW 则拆。</li><li>换 TLB 效率，付碎片与尾延迟。</li><li>KSM 是下一课。</li><li>出处：Linux transhuge；Navarro 超级页；Gorman。</li></ul>',11))])}const A=s(h,[["render",m]]);export{g as __pageData,A as default};
